if Bldg == 35053
    hazardData = Hazard_Guwahati_Sa_0p71_Z5;
elseif Bldg == 46053
    hazardData = Hazard_Guwahati_Sa_0p71_Z6;
else
    error('Hazard data not defined for Building %d',Bldg);
end


%% Risk Calculation Settings
imOrAfeBound = 1;      % no bound (=0); bound over IM (=1); bound over AFE (=2)
lowerBound   = 0.01;   % assign 99 to indicate that lowerBound is taken as the minimum im Value from fragility analysis
upperBound   = 5.00;   % lower bound bound (over im or afe, as may be the case)

boundRange = [lowerBound upperBound];

%% Initialize
nDS = length(theta);

riskVal         = zeros(1,nDS);
highestContriIM = zeros(1,nDS);
modalImRatio    = zeros(1,nDS);

%% Compute Risk for Each Damage State
for iDS = 1:nDS

    fragilityData = [theta(iDS) beta(iDS)];

    [riskVal(iDS), highestContriIM(iDS), modalImRatio(iDS)] = computeRiskSingleSite_v3(hazardData, fragilityData, imOrAfeBound, boundRange);

end

%% Display Results
% Damage State Labels
DS = {'IO'; 'LS'; 'CP'; 'Collapse'};

% Display Results
Risk_AFE_x1e4 = riskVal(:)*1e4;

Results = table(DS, theta(:), beta(:), Risk_AFE_x1e4, highestContriIM(:), modalImRatio(:), ...
    'VariableNames', {'DamageState','Theta','Beta', 'Risk_AFE_x10m4','HighestContriIM','ModalIMRatio'});

