%     'VariableNames', {'DamageState', 'Theta', 'Beta', 'Risk_AFE', 'HighestContriIM', 'ModalIMRatio'});

disp(' ');
disp(['Building ID = ',num2str(Bldg)]);
disp(Results);

%% Optional: Probability in 50 years
Prob50yr = 100*(1-exp(-riskVal*50));

Results.ProbExceed50yr_percent = Prob50yr(:);

disp(' ');
disp('Including probability of exceedance in 50 years:');
disp(Results);